fn sum(a: &Vec<u32>, b: &Vec<u32>) -> Vec<u32> {
    // The two input vectors are guaranteed to have the same length (≤ 100),
    // and for each index i, a[i] + b[i] < 1000, so u32 addition will not overflow.
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");

    // Pre-allocate output vector with the same capacity as the inputs
    let mut c = Vec::with_capacity(a.len());

    // Compute element-wise sums
    for (&x, &y) in a.iter().zip(b.iter()) {
        c.push(x + y);
    }

    c
}

